[{"order":1,"type":"heading","text":"Spring Boot Actuator: Monitoring and Management of Applications"},{"order":2,"type":"paragraph","text":"Spring Boot Actuator provides production-ready features to help you monitor and manage your Spring Boot application. It exposes operational information about your application, such as health, metrics, info, dump, env, and more, through HTTP endpoints or JMX."},{"order":3,"type":"heading","text":"Adding Spring Boot Actuator to Your Project"},{"order":4,"type":"paragraph","text":"To include Spring Boot Actuator in your project, add the following dependency to your `pom.xml` (for Maven) or `build.gradle` (for Gradle)."},{"order":5,"type":"subheading","text":"Maven (pom.xml)"},{"order":6,"type":"code","text":"<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-actuator</artifactId>
</dependency>"},{"order":7,"type":"subheading","text":"Gradle (build.gradle)"},{"order":8,"type":"code","text":"dependencies {
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
}"},{"order":9,"type":"paragraph","text":"After adding the dependency, rebuild your project. Spring Boot Actuator will be automatically configured."},{"order":10,"type":"heading","text":"Actuator Endpoints"},{"order":11,"type":"paragraph","text":"Actuator endpoints allow you to monitor and interact with your application. The following are some of the most commonly used endpoints:"},{"order":12,"type":"bullet_point","text":"`health`: Shows application health information (e.g., status, disk space, database connection)."},{"order":13,"type":"bullet_point","text":"`info`: Displays arbitrary application information (e.g., build version, git commit ID)."},{"order":14,"type":"bullet_point","text":"`metrics`: Exposes application metrics (e.g., memory usage, HTTP request counts)."},{"order":15,"type":"bullet_point","text":"`env`: Exposes the application's environment properties."},{"order":16,"type":"bullet_point","text":"`loggers`: Shows and modifies the configuration of loggers in the application."},{"order":17,"type":"bullet_point","text":"`heapdump`: Returns a heap dump for the JVM."},{"order":18,"type":"bullet_point","text":"`threaddump`: Performs a thread dump."},{"order":19,"type":"subheading","text":"Accessing Endpoints"},{"order":20,"type":"paragraph","text":"By default, most actuator endpoints are disabled. To enable them, you need to configure the `management.endpoints.web.exposure.include` property in your `application.properties` or `application.yml` file."},{"order":21,"type":"subheading","text":"application.properties"},{"order":22,"type":"code","text":"management.endpoints.web.exposure.include=health,info,metrics"},{"order":23,"type":"subheading","text":"application.yml"},{"order":24,"type":"code","text":"management:
  endpoints:
    web:
      exposure:
        include: health,info,metrics"},{"order":25,"type":"paragraph","text":"To expose all endpoints, you can use `*`:"},{"order":26,"type":"code","text":"management.endpoints.web.exposure.include=*"},{"order":27,"type":"paragraph","text":"After configuring the exposed endpoints, you can access them via HTTP. For example, if your application is running on `localhost:8080`, you can access the health endpoint at `http://localhost:8080/actuator/health`."},{"order":28,"type":"heading","text":"Securing Actuator Endpoints"},{"order":29,"type":"paragraph","text":"It's crucial to secure your actuator endpoints, especially in production environments. You can use Spring Security to protect them."},{"order":30,"type":"paragraph","text":"First, add the Spring Security dependency to your project:"},{"order":31,"type":"subheading","text":"Maven (pom.xml)"},{"order":32,"type":"code","text":"<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-security</artifactId>
</dependency>"},{"order":33,"type":"subheading","text":"Gradle (build.gradle)"},{"order":34,"type":"code","text":"dependencies {
    implementation 'org.springframework.boot:spring-boot-starter-security'
}"},{"order":35,"type":"paragraph","text":"Next, create a configuration class to define security rules. Here's an example:"},{"order":36,"type":"code","text":"import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;

import static org.springframework.security.config.Customizer.withDefaults;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests((authz) -> authz
                .requestMatchers("/actuator/**").hasRole("ACTUATOR")
                .anyRequest().permitAll()
            )
            .httpBasic(withDefaults());
        return http.build();
    }
}"},{"order":37,"type":"paragraph","text":"This configuration requires users with the `ACTUATOR` role to access actuator endpoints. You'll also need to configure a user with this role.  You can do this in your `application.properties` or `application.yml`:"},{"order":38,"type":"subheading","text":"application.properties"},{"order":39,"type":"code","text":"spring.security.user.name=actuator
spring.security.user.password=secret
spring.security.user.roles=ACTUATOR"},{"order":40,"type":"subheading","text":"application.yml"},{"order":41,"type":"code","text":"spring:
  security:
    user:
      name: actuator
      password: secret
      roles: ACTUATOR"},{"order":42,"type":"paragraph","text":"Now, accessing actuator endpoints will require authentication with the username `actuator` and password `secret`."},{"order":43,"type":"heading","text":"Customizing Actuator Endpoints"},{"order":44,"type":"paragraph","text":"You can customize the behavior of actuator endpoints. For example, you can add custom health indicators or info contributors."},{"order":45,"type":"subheading","text":"Custom Health Indicator"},{"order":46,"type":"paragraph","text":"Create a class that implements the `HealthIndicator` interface:"},{"order":47,"type":"code","text":"import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

@Component
public class MyCustomHealthIndicator implements HealthIndicator {

    @Override
    public Health health() {
        int errorCode = check(); // Perform some specific health check
        if (errorCode != 0) {
            return Health.down()
                    .withDetail("Error Code", errorCode).build();
        }
        return Health.up().build();
    }

    private int check() {
        // Your custom health check logic here
        return 0; // Return 0 for healthy, non-zero for unhealthy
    }
}"},{"order":48,"type":"paragraph","text":"This example creates a custom health indicator that performs a specific check and returns a `Health` object indicating the application's health status."},{"order":49,"type":"subheading","text":"Custom Info Contributor"},{"order":50,"type":"paragraph","text":"Create a class that implements the `InfoContributor` interface:"},{"order":51,"type":"code","text":"import org.springframework.boot.actuate.info.Info;
import org.springframework.boot.actuate.info.InfoContributor;
import org.springframework.stereotype.Component;

import java.util.HashMap;
import java.util.Map;

@Component
public class MyCustomInfoContributor implements InfoContributor {

    @Override
    public void contribute(Info.Builder builder) {
        Map<String, String> details = new HashMap<>();
        details.put("application-name", "My Awesome App");
        details.put("version", "1.0.0");
        builder.withDetail("custom-info", details);
    }
}"},{"order":52,"type":"paragraph","text":"This example adds custom information to the `/actuator/info` endpoint."},{"order":53,"type":"heading","text":"Conclusion"},{"order":54,"type":"paragraph","text":"Spring Boot Actuator is a powerful tool for monitoring and managing your Spring Boot applications. By exposing operational information through endpoints, it enables you to gain insights into your application's health, performance, and environment. Remember to secure your actuator endpoints, especially in production environments, to prevent unauthorized access."}]
